effect.shader:

    vec4 newLayer( vec4 a, vec4 b) {
    return a * (1. - b.a) + b;
    }

    mat2 rot2m(float a){

	float s = sin(a);
	float c = cos(a);

	return mat2(c, -s, s, c);
    }

    vec2 l2s( vec2 v ) {
        return (vec4(v,0.,1.)*acLayerToScreen).xy;
    }

   #define fragCoord gl_FragCoord.xy

   /////////////////////////

        vec2 distortUV(vec2 uv, vec2 nUV)
        {            

            nUV.x += warpx*speed;
            nUV.y += warpy*speed;
            vec2 noise= texture2DCv( noisexx.texture, nUV*amp).xy;

            uv += (-1.0+noise*2.0) * intensity;

            return uv;
        }

   /////////////////////////
    void main ()
    {

        vec4 texColor = texture2DCv(inputImg.texture,acScreenNorm);

        vec2 TanRyu;
        TanRyu = acScreenNorm;

        TanRyu /= scaleuv;
        TanRyu += vec2((0.0+position.x), (0.0+position.y))*vec2(-1.,1.)/500.;
        vec2 scaleVec;
        scaleVec = vec2(scaleuv*stretch.x,scaleuv*stretch.y);
        TanRyu /= scaleVec;        
        /////////////////////////

    	vec4 fragColor;

            vec2 uv = TanRyu;
            vec2 nUV = uv;

            uv = distortUV(uv, vec2(nUV.x,nUV.y));

            vec4 color= texture2DCv( inputImg.texture, uv);

    	gl_FragColor = color;
    	// }
    }
